CREATE TABLE "public"."definitions" (
  "id"              bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "headword_id"     bigint,
  "user_id"         uuid,
  "dialect_id"      integer,
  "definition_text" text                     NOT NULL,
  "attributes"      jsonb                    DEFAULT '{}'::jsonb,
  "audio_url"       text,
  "is_verified"     boolean                  DEFAULT false,
  "verified_by"     uuid,
  "vote_score"      integer                  DEFAULT 0,
  "created_at"      timestamp with time zone DEFAULT now(),
  "updated_at"      timestamp with time zone DEFAULT now(),
  "language_code"   text                     NOT NULL DEFAULT 'en'::text,
  CONSTRAINT "definitions_pkey" PRIMARY KEY (id),
  CONSTRAINT "definitions_dialect_id_fkey" FOREIGN KEY (dialect_id) REFERENCES public.dialects(id),
  CONSTRAINT "definitions_headword_id_fkey" FOREIGN KEY (headword_id) REFERENCES public.headwords(id) ON DELETE CASCADE,
  CONSTRAINT "definitions_user_id_fkey" FOREIGN KEY (user_id) REFERENCES public.profiles(id),
  CONSTRAINT "definitions_verified_by_fkey" FOREIGN KEY (verified_by) REFERENCES public.profiles(id)
);

CREATE TRIGGER set_timestamp_definitions
  BEFORE UPDATE ON public.definitions
  FOR EACH ROW
  EXECUTE FUNCTION public.update_timestamp();

REVOKE ALL ON SEQUENCE "public"."definitions_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."definitions_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."definitions_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."definitions_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."definitions_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."definitions_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."definitions_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."definitions_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."definitions" TO "anon", "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."definitions" TO "service_role";

REVOKE ALL ON TABLE "public"."definitions" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."definitions" TO "postgres";
